static const char __pyx_k_e1A_1A_iq_t4q_r_A_q_a_5_5_b_1_7[] = "\200\001\360\036\000\005\017\210e\2201\220A\330\004\010\210\003\2101\210A\330\004\016\210i\220q\230\001\340\004\007\200t\2104\210q\220\n\230&\240\001\330\004\007\200r\210\023\210A\330\010\017\210q\340\004\016\210a\330\004\013\2105\220\001\220\021\330\004\010\210\003\2105\220\t\230\021\230!\330\010\016\210b\220\003\2201\330\014\023\2207\230!\2301\330\014\021\220\024\220T\230\021\230*\240F\250!\330\014\017\210t\2203\220a\330\020\021\330\014\020\220\001\330\010\013\2102\210S\220\001\330\014\r\340\010\016\210j\230\001\330\014\r\340\004\010\210\003\2101\210A\330\004\022\220!\2203\220b\230\001\330\004\010\210\005\210Q\330\010\023\2201\220F\230!\340\004\014\210A\330\004\025\220Q\330\004\010\210\005\210U\220!\2203\220a\330\010\032\230+\240Q\240b\250\002\250!\330\010\014\210B\210b\220\002\220\"\220B\220b\230\002\230\"\230A\330\010\014\210B\210b\220\001\330\010\013\2102\210S\220\001\330\014\025\220T\230\021\230#\230Q\340\004\013\2101";
static const char __pyx_k_element_is_not_a_combination_of[] = "element is not a combination of iterable";
static const char __pyx_k_func_run_length_encode_compress[] = ":func:`run_length.encode` compresses an iterable with run-length encoding.\n\n    It yields groups of repeated items with the count of how many times they\n    were repeated:\n\n        >>> uncompressed = 'abbcccdddd'\n        >>> list(run_length.encode(uncompressed))\n        [('a', 1), ('b', 2), ('c', 3), ('d', 4)]\n\n    :func:`run_length.decode` decompresses an iterable that was previously\n    compressed with run-length encoding. It yields the items of the\n    decompressed iterable:\n\n        >>> compressed = [('a', 1), ('b', 2), ('c', 3), ('d', 4)]\n        >>> list(run_length.decode(compressed))\n        ['a', 'b', 'b', 'c', 'c', 'c', 'd', 'd', 'd', 'd']\n\n    ";
static const char __pyx_k_interleave_evenly_locals_lambda[] = "interleave_evenly.<locals>.<lambda>";
static const char __pyx_k_iq_t4q_r_A_q_a_9AQ_5_2S_7_1_T_F[] = "\200\001\360\032\000\005\017\210i\220q\230\001\330\004\007\200t\2104\210q\220\n\230&\240\001\330\004\007\200r\210\023\210A\330\010\017\210q\340\004\016\210a\330\004\013\2109\220A\220Q\330\004\010\210\003\2105\220\001\330\010\013\2102\210S\220\001\330\014\023\2207\230!\2301\330\014\021\220\024\220T\230\021\230*\240F\250!\330\014\017\210t\2203\220a\330\020\021\330\014\020\220\001\340\010\016\210j\230\001\230\021\340\004\007\200t\2104\210q\220\006\220i\230s\240!\360\006\000\005\r\210A\330\004\010\210\003\2105\220\t\230\021\230(\240!\240:\250V\2601\330\010\014\210B\210b\220\001\330\010\013\2102\210S\220\001\330\014\025\220T\230\021\230#\230Q\340\004\013\2104\210q\220\002\220\"\220C\220r\230\022\2303\230b\240\001";
